internal class GUPBasePriceActivationJob extends RunBaseBatch implements BatchRetryable
{
    #OCCRetryCount

    private QueryRun                    queryRun;

    private NoYes                       netWeight;
    private NoYes                       rateAndRatio;
    private NoYes                       controlDate;
    private NoYes                       skipActivationIfEqualPriceExists;
    private NoYes                       abortOnError;
    private NoYes                       recalculateProduction;

    private GUPBasePriceVersionId       fromVersion;

    private BatchHeader                 currentBatchHeader;

    private DialogField                 dialogFieldNetWeight;
    private DialogField                 dialogFieldRateAndRatio;
    private DialogField                 dialogFieldControlDate;
    private DialogField                 dialogFieldControlExistingPrice;
    private DialogField                 dialogFieldAbortOnError;
    private DialogField                 dialogFieldRecalculateProduction;

    private boolean                     doNotUpdateLastActivationDate;

    private boolean                     activateItemYesToAll = false;
    private boolean                     activateItemNoToAll = false;
    private boolean                     activateItemCancel = false;

    #DEFINE.CurrentVersion(1)

    #LOCALMACRO.CurrentList
        netWeight,
        rateAndRatio,
        controlDate,
        skipActivationIfEqualPriceExists,
        fromVersion,
        abortOnError,
        recalculateProduction
    #ENDMACRO

}

Method.Source:
public static GUPBasePriceActivationJob construct()
{
    return new GUPBasePriceActivationJob();
}

public void initParmDefault()
{
    super();

    Query query = new Query();
    query.addDataSource(tableNum(GUPItemBasePriceSim));

    query.dataSourceTable(tableNum(GUPItemBasePriceSim)).addRange(fieldNum(GUPItemBasePriceSim, VersionId)).status(RangeStatus::Hidden);
    query.dataSourceTable(tableNum(GUPItemBasePriceSim)).addRange(fieldNum(GUPItemBasePriceSim, FromDate)).status(RangeStatus::Hidden);
    query.dataSourceTable(tableNum(GUPItemBasePriceSim)).addRange(fieldNum(GUPItemBasePriceSim, PriceType)).status(RangeStatus::Hidden);

    queryRun = new QueryRun(query);
}

public boolean unpack(container packedClass)
{
    container   packedQuery;
    Integer     version         = RunBase::getVersion(packedClass);

    switch (version)
    {
        case #CurrentVersion :
            [version, #CurrentList, packedQuery] = packedClass;

            if (packedQuery)
            {
                queryRun = new QueryRun(packedQuery);
            }
            break;

        default :
            return false;
    }

    return true;
}

public Object dialog()
{
    DialogRunbase dialog = super();

    dialog.addGroup("@SYS121351");
    dialog.addFieldValue(extendedTypeStr(GUPBasePriceVersionId), fromVersion).enabled(false);
    dialog.addFieldValue(extendedTypeStr(GUPBasePriceVersionName), GUPBasePriceVersion::find(fromVersion).Name).enabled(false);
    dialog.addGroup("@SYS121350");
    dialogFieldNetWeight            = dialog.addFieldValue(enumStr(NoYes), netWeight, "@SYS23743");
    dialogFieldRateAndRatio         = dialog.addFieldValue(enumStr(NoYes), rateAndRatio, "@SYS104960");

    dialog.addGroup("@SYS53323");
    dialogFieldControlDate          = dialog.addFieldValue(enumStr(NoYes), controlDate, "@SYS24050", "@SYS104995");
    dialogFieldControlExistingPrice = dialog.addFieldValue(enumStr(NoYes), skipActivationIfEqualPriceExists, "@SYP4882093", "@SYP4882094");

    dialog.addGroup("@SYS107201");
    dialogFieldAbortOnError         = dialog.addFieldValue(enumStr(NoYes), abortOnError, "@SYS105290", "@SYS105290");

    dialog.addGroup("@SYS4009911");
    dialogFieldRecalculateProduction = dialog.addFieldValue(enumStr(NoYes), recalculateProduction, "@SYS4009912");

    return dialog;
}

public boolean getFromDialog()
{
    boolean ret = super();

    netWeight                           = dialogFieldNetWeight.value();
    rateAndRatio                        = dialogFieldRateAndRatio.value();
    controlDate                         = dialogFieldControlDate.value();
    skipActivationIfEqualPriceExists    = dialogFieldControlExistingPrice.value();
    abortOnError                        = dialogFieldAbortOnError.value();
    recalculateProduction               = dialogFieldRecalculateProduction.value();

    return ret;
}

public boolean activateItemDialogCheck(GUPItemBasePriceSim _itemBasePriceSim)
{
    GUPItemBasePrice    currentItemBasePrice;
    boolean             doActivate = true;
    DialogButton        userResponse;

    if (this.activateItemNoToAll)
    {
        doActivate = false;
    }
    else
    {
        currentItemBasePrice = GUPItemBasePrice::findExistingActiveBasePrice(
                                    _itemBasePriceSim.ItemId,
                                    _itemBasePriceSim.PriceType,
                                    _itemBasePriceSim.InventDimId,
                                    _itemBasePriceSim.FromDate,
                                    _itemBasePriceSim.ToDate);

        if (currentItemBasePrice)
        {
            userResponse = Box::yesAllNoAllCancel(strFmt("@GlobalUnifiedPricing:GUPItemActivateOverwriteWarning",
                                currentItemBasePrice.ItemId,
                                currentItemBasePrice.VersionId,
                                currentItemBasePrice.FromDate,
                                date2StrUsr(_itemBasePriceSim.FromDate, DateFlags::FormatAll)), DialogButton::No);

            if (userResponse == DialogButton::No || userResponse == DialogButton::NoToAll || userResponse == DialogButton::Cancel)
            {
                doActivate = false;
            }

            activateItemCancel = userResponse == DialogButton::Cancel;
            activateItemNoToAll = userResponse == DialogButton::NoToAll;
            activateItemYesToAll = userResponse == DialogButton::YesToAll;
        }
    }

    return doActivate;
}

public static void main(Args args)
{
    GUPBasePriceActivationJob itemBasePriceActivationJob  = GUPBasePriceActivationJob::construct();

    using (SysErrorMessageHelpScope scope = SysErrorMessageHelpScope::newErrorContext(args))
    {
        if (args && args.record() && args.dataset() == tableNum(GUPItemBasePriceSim))
        {                
            FormDataSource itemBasePriceSimDS = FormDataUtil::getFormDataSource(args.record());
            for (Common record = itemBasePriceSimDS.getFirst(true)
                        ? itemBasePriceSimDS.getFirst(true)
                        : itemBasePriceSimDS.cursor();
            record && !itemBasePriceActivationJob.activateItemCancel;
            record = itemBasePriceSimDS.getNext())
            {
                GUPItemBasePriceSim itemBasePriceSim = record as GUPItemBasePriceSim;

                if (itemBasePriceSim.allowActivation(false) && (itemBasePriceActivationJob.activateItemYesToAll || itemBasePriceActivationJob.activateItemDialogCheck(itemBasePriceSim)))
                {
                    itemBasePriceActivationJob.activateOneItemBasePriceSim(itemBasePriceSim);
                }
            }                        
        }
        else
        {
            throw error(Error::missingRecord(funcName()));
        }
    }
}

public boolean activePriceJobByVersionId(GUPBasePriceVersionId _versionid, boolean noDialog = false)
{
    boolean                             ret = true;
    boolean                             noActivePrice;
    GUPItemBasePriceSim                 itemBasePriceSim;
    GUPBasePriceActivationJob           itemBasePriceActivationJob;

    itemBasePriceActivationJob  = GUPBasePriceActivationJob::construct();

    ttsbegin;

    while select * from itemBasePriceSim where itemBasePriceSim.VersionId == _versionid
    {
        if (itemBasePriceActivationJob.activateItemCancel)
        {
            break;
        }

        itemBasePriceSim.selectForUpdate(true);
        noActivePrice = itemBasePriceSim.checkNoActivePrice(false);

        if (itemBasePriceSim.allowActivation(false) && (noDialog == true || (itemBasePriceActivationJob.activateItemYesToAll || itemBasePriceActivationJob.activateItemDialogCheck(itemBasePriceSim))))
        {

            itemBasePriceActivationJob.activateOneItemBasePriceSim(itemBasePriceSim);
        }           
    }

    ttscommit;

    return ret;
}

public boolean parmDoNotUpdateLastActivationDate(boolean _doNotUpdateLastActivationDate = doNotUpdateLastActivationDate)
{
    doNotUpdateLastActivationDate = _doNotUpdateLastActivationDate;
    return doNotUpdateLastActivationDate;
}

protected boolean activateOneItemBasePriceSim(GUPItemBasePriceSim _baseItemPriceSim)
{
    boolean priceActivated = false;
    GUPItemBasePriceSim baseItemPriceSim = _baseItemPriceSim;
    GUPBasePriceVersion basePriceVersion;

    #OCCRetryCount

    try
    {            
        if (!doNotUpdateLastActivationDate && baseItemPriceSim.FromDate != DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()))
        {
            info(strFmt("@GlobalUnifiedPricing:GUPBasePriceActivationDateUpdate", baseItemPriceSim.ItemId, date2StrUsr(baseItemPriceSim.FromDate, DateFlags::FormatAll), date2StrUsr( DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()), DateFlags::FormatAll)));
        }

        ttsbegin;

        baseItemPriceSim.moveSimulatedToCurrent();

        if (!doNotUpdateLastActivationDate)
        {
            GUPBasePriceVersion::updateActivationDate(baseItemPriceSim.VersionId);
        }

        ttscommit;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    return priceActivated;
}
